#!/usr/bin/env python3
"""Build draft Guide Me bindings for the 25 approved foundational fraction/decimal sources."""
import gzip,json,re
from fractions import Fraction as F
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];D=Path(__file__).resolve().parent
S=json.loads(gzip.decompress((D/'bulk-state.json.gz').read_bytes()))
def option(i,text,role,feedback):return {'id':i,'text':text,'role':role,'feedback':feedback}
def main():
 a=json.loads((D/'foundation65-audit-v0.1.json').read_text());cache={};items=[]
 for r in a['items']:
  if r['source_status']!='approved':continue
  row=next(x for x in S['records'] if x['question_id']==r['question_id'])
  if row['source_file'] not in cache:cache[row['source_file']]={q['id']:q for q in json.loads((ROOT/row['source_file']).read_text())['items']}
  q=cache[row['source_file']][r['question_id']];stem=q['stem'];method=r['method'];solution=[];hints=[]
  if method=='successive-fractions-of-remaining':
   p=re.search(r'had ([\d,]+) [^.]+\. It gave out (\d+/\d+) of them.*? and (\d+/\d+) of the remaining',stem,re.I);assert p
   total=F(p[1].replace(',',''));first=F(p[2]);second=F(p[3]);remaining=total*(1-first);left=remaining*(1-second)
   diag={'prompt':f'Tuesday gives out {p[3]} of the remaining items. What does that fraction apply to?','choices':[option('new-remainder','The amount left after Monday.','correct-rule','Yes. The word “remaining” resets the base to what is left after Monday.'),option('original-total','The original amount from the start.','common-error','That would be correct only if the question said the Tuesday fraction was of the original total. Here it says “of the remaining.”'),option('monday-given','Only the amount given out on Monday.','common-error','The fraction applies to what is still left after Monday, not to the amount already given out.'),option('unsure','I am unsure, guessed, or selected by mistake.','uncertain','No cause is established. Let’s find the amount remaining after Monday first.')],'confirmation':'Was this the base you used originally, or did you choose it after seeing the options?'}
   solution=[f'Start with {total}. Monday gives out {first} × {total} = {total*first}.',f'After Monday, {total} − {total*first} = {remaining} remain.',f'Tuesday gives out {second} × {remaining} = {remaining*second}.',f'Subtract Tuesday’s amount: {remaining} − {remaining*second} = {left} left.']
   hints=['Find Monday’s amount and subtract it from the starting amount.','Apply Tuesday’s fraction to the smaller remainder, then subtract that amount.']
  else:
   tpls={
    'fraction-addition':('Before adding fractions, what should you do with their denominators?','common-denominator',[('same','Rewrite both fractions with a common denominator.','correct-rule','Right. Equivalent fractions with a shared denominator can be added by combining their numerators.'),('add-denominators','Add the denominators directly.','common-error','The denominator names the size of the parts. First express both amounts using the same-sized parts.'),('numerators-only','Add numerators and keep the first denominator.','common-error','This can combine different-sized parts incorrectly. Make the denominators match first.'),('unsure','I am unsure, guessed, or selected by mistake.','uncertain','No cause is established. We can find a common-sized part before adding.')]),
    'decimal-multiplication':('What is a reliable way to estimate a product when one factor is 0.04?','decimal-place-value',[('hundredth','0.04 is four hundredths, so the product is four hundredths of the other factor.','correct-rule','Correct. The value of 0.04 is 4/100, not 4.'),('use-four','Treat 0.04 as 4 and multiply.','common-error','That drops the hundredths place and makes the result 100 times too large.'),('add','Add the two factors.','common-error','The operation is multiplication. Use 0.04 as four hundredths of the other amount.'),('unsure','I am unsure, guessed, or selected by mistake.','uncertain','No cause is established. Rewrite 0.04 as 4/100 and estimate the size.')]),
    'decimal-division':('When dividing by 0.08, how can you make the divisor a whole number without changing the quotient?','equivalent-quotient',[('both','Multiply both the dividend and divisor by 100.','correct-rule','Yes. Scaling both numbers equally preserves the quotient and changes 0.08 to 8.'),('divisor-only','Move the divisor decimal two places but leave the dividend unchanged.','common-error','Changing only one number changes the quotient. Apply the same scale factor to both.'),('times-ten','Multiply both by 10, leaving the divisor as 0.8.','common-error','That keeps the quotient but does not yet make the divisor whole. Use a factor of 100.'),('unsure','I am unsure, guessed, or selected by mistake.','uncertain','No cause is established. Choose a scale factor that turns 0.08 into 8.')]),
    'compare-fractions-and-decimals':('How can you compare 0.6, 5/8, 0.58, and 3/5 fairly?','common-scale',[('same-form','Convert each value to the same form, then compare.','correct-rule','Correct. For example, 0.6 = 0.60 and 5/8 = 0.625, so their sizes can be compared directly.'),('numerator','Compare only the numerators of the fractions.','common-error','The denominator changes the size of each fractional part. Compare equivalent values instead.'),('digits','Assume more written decimal digits means a larger number.','common-error','Trailing zeros do not change value. Align place values, or use a common denominator.'),('unsure','I am unsure, guessed, or selected by mistake.','uncertain','No cause is established. Convert the fractions to decimals or to a common denominator.')]),
    'fractions-of-the-same-whole-remaining':('The problem says both fractions are of the same ream. What is the second fraction based on?','same-original-whole',[('same-whole','The original 500-sheet ream.','correct-rule','Yes. “Of the same ream” keeps the original whole as the base for both fractions.'),('remainder','The amount left after Monday.','common-error','That would apply if the wording said “of the remaining.” Here both fractions refer to the same original ream.'),('monday-use','The number of sheets used Monday.','common-error','The second fraction is of the ream, not of Monday’s used amount.'),('unsure','I am unsure, guessed, or selected by mistake.','uncertain','No cause is established. Keep the original whole separate from the amount already used.')]),
    'fraction-multiplication':('Before multiplying a mixed number by a fraction, what should you do with the mixed number?','mixed-to-improper',[('convert','Convert it to an improper fraction.','correct-rule','Yes. Then multiply numerators and denominators and simplify.'),('multiply-whole','Multiply only the whole-number part.','common-error','That leaves out the fractional part. Convert the entire mixed number first.'),('add-parts','Add the numerator and denominator to the whole number.','common-error','A mixed number represents a whole amount plus a fraction, not a sum of its written digits.'),('unsure','I am unsure, guessed, or selected by mistake.','uncertain','No cause is established. Write the mixed number as one improper fraction first.')])}
   prompt,concept,choices=tpls[method]
   diag={'prompt':prompt,'choices':[option(*c) for c in choices],'confirmation':'Was this the method you used before answering, or is this a new insight?'}
   if method=='fraction-addition':solution=['Rewrite both fractions with denominator 12.','3/4 = 9/12 and 5/6 = 10/12.','9/12 + 10/12 = 19/12 = 1 7/12.'];hints=['Find a common denominator, such as the least common multiple.','Rewrite each fraction equivalently, then add the numerators.']
   elif method=='decimal-multiplication':solution=['2.5 × 0.04 = 2.5 × 4/100.','2.5 × 4 = 10; 10/100 = 0.10 = 0.1.'];hints=['Rewrite 0.04 as 4/100.','Multiply by 4, then divide by 100.']
   elif method=='decimal-division':solution=['Multiply both numbers by 100: 7.2 ÷ 0.08 = 720 ÷ 8.','720 ÷ 8 = 90.'];hints=['Choose a power of ten that makes 0.08 a whole number.','Scale the dividend by the same factor, then divide.']
   elif method=='compare-fractions-and-decimals':solution=['0.6 = 0.60; 3/5 = 0.60; 0.58 = 0.58; 5/8 = 0.625.','0.625 is greatest, so 5/8 is greatest.'];hints=['Convert all values to decimals or a common denominator.','Compare their values after conversion.']
   elif method=='fractions-of-the-same-whole-remaining':solution=['Monday: 2/5 × 500 = 200 sheets.','Tuesday: 1/4 × 500 = 125 sheets, using the original whole as the base.','Left: 500 − 200 − 125 = 175 sheets.'];hints=['Both fractions use the original 500-sheet ream.','Find each part of 500, then subtract both used amounts.']
   else:solution=['Convert 1 2/3 to 5/3.','5/3 × 3/5 = 15/15 = 1.'];hints=['Write the mixed number as an improper fraction.','Multiply across, then simplify.']
  key=next(o['text'] for o in q['options'] if o['option_id']==q['answer_option_id'])
  items.append({'question_id':q['id'],'source_file':row['source_file'],'source_record_sha256':row['source_record_sha256'],'bank_status_at_authoring':'approved','method':method,'diagnostic':diag,'hints':hints,'worked_solution':solution,'verified_answer':{'option_id':q['answer_option_id'],'value':r['calculation'],'source_key_text':key,'exact_check_passed':r['key_matches']},'canonical_explanation':q['reveal']['why_correct'],'transfer':{'approved_question_id':None,'status':'gap_unresolved'},'assistance_contract':{'diagnostic_is_assisted':True,'diagnostic_does_not_establish_mastery':True,'uncertain_or_misclick_assigns_no_hypothesis':True,'confirmation_is_self_report_only':True},'status':'draft','editorial_review':None,'runtime_eligible':False})
 data={'schema_version':'dexter-foundation65-guide-v0.1','baseline_commit':'d215839e34884296e61bdce7c16961df02f0a74a','status':'draft','runtime_eligible':False,'human_review':None,'learner_evidence':None,'bindings':items,'excluded_nonapproved_ids':[r['question_id'] for r in a['items'] if r['source_status']!='approved'],'notes':['The audit covers 65 fraction, decimal, percentage and basic-operation items.','The tutoring sidecar includes only 25 approved-source items; 40 reviewed/draft records are excluded.','Nineteen approved items repeat one two-day successive-remainder structure.','All tutoring diagnostics and retries are assisted; no key, approval, source, or runtime state was changed.','No distinct-family transfer was independently verified.']}
 (D/'foundation65-guide-draft-v0.1.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');print('draft bindings',len(items),'excluded',len(data['excluded_nonapproved_ids']))
if __name__=='__main__':main()
